#!/usr/bin/env bash
#EXP gpus=1 cpus=8 mem=96G time=12:00:00 part=preempt exclude=babel-l9-32
# HYPOTHESIS: E3g collapse-rate test, seed 5: d4+d6 without d8. So far collapse 2/3 with d8 vs 0/3 without (p=0.4). no_ckpt (a preemption restarts from round 0).
# Generated by qis.s02.make_exps (study Nov-15-2026-02). Bundle s02-v1 = add9:d4,add9:d6,add9:d8,caesar:s4,caesar:s8,caesar:s12,mbpp:all,arc:all,countdown:n3,countdown:n4,terse10:k2:3000,add10:d14 (n_train 4000, n_eval 64).
export PROJ_DATA="/data/user_data/$USER/qis"
export S02="$PROJ_DATA/s02"
export VENV="$PROJ_DATA/env/venv-s02"
export HF_HOME="$PROJ_DATA/hf"
export HF_HUB_OFFLINE=1
export PYTHONPATH="$PWD/src"
export VLLM_ENABLE_V1_MULTIPROCESSING=0
export VLLM_USE_FLASHINFER_SAMPLER=0
export PATH="$VENV/bin:$PATH"
export MODEL="$PROJ_DATA/hf/hub/models--Qwen--Qwen3-1.7B/snapshots/70d244cc86ccca08cf5af4e1e306ecf908b1ad5e"
export BUNDLE="$S02/data/s02-v1.json"
export BSPEC="add9:d4,add9:d6,add9:d8,caesar:s4,caesar:s8,caesar:s12,mbpp:all,arc:all,countdown:n3,countdown:n4,terse10:k2:3000,add10:d14"
export RUN="qis-s02-e3-add9d4d6-s5"
export W="$S02/runs/$RUN"
export CK="$S02/ckpt/$RUN"
export CFG_JSON='{"phase": "e3a", "seed": 5, "lr": 2e-06, "eps_low": 0.2, "eps_high": 0.2, "grad_clip": 1.0, "rounds": 32, "ckpt_every": 8, "eval_rounds": [0, 4, 8, 12, 16, 24, 32], "eval_panels": {"caesar_s4_sel": 4, "caesar_s8_sel": 4, "caesar_s12_sel": 4, "add9_d4_sel": 4, "add9_d6_sel": 4, "add9_d8_sel": 4, "mbpp_all_sel": 4, "arc_all_sel": 4, "countdown_n3_sel": 4, "add10_d14_sel": 4, "terse10_k2_sel": 4}, "max_tokens": 4096, "gpu_mem_util": 0.3, "max_num_seqs": 256, "n_per_prompt": 8, "n_minibatch": 4, "loss_norm_responses": 32, "mix": [{"role": "T", "pool": "add9_d4_train", "slots": 3}, {"role": "T", "pool": "add9_d6_train", "slots": 3}], "wandb": {"enabled": false}, "retain_rounds": [], "allow_uneven_minibatch": true, "no_ckpt": true}'
phase precheck "false" '
    test -f "$VENV/.complete" || { echo "PRECONDITION FAILED: venv-s02 missing"; exit 1; }
    used=$(nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits | head -1)
    [ "$used" -lt 2048 ] || { echo "GPU already holds ${used} MiB on $(hostname)"; exit 1; }
    nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv > "$AE_RESULTS/gpu.txt"
    free=$(df -BG --output=avail "$PROJ_DATA" | tail -1 | tr -dc 0-9)
    [ "$free" -ge 60 ] || { echo "PRECONDITION FAILED: $PROJ_DATA has ${free}G free < 60G"; exit 1; }
    mkdir -p "$W" "$CK" "$S02/data"
'
phase tests "test -s $W/pytest.ok" '
    rc=0; env CUDA_VISIBLE_DEVICES= python -m pytest -q -p no:cacheprovider tests/test_s02.py tests/test_grpo.py > "$AE_RESULTS/pytest.txt" 2>&1 || rc=$?
    tail -n 2 "$AE_RESULTS/pytest.txt"; [ $rc -eq 0 ] && touch "$W/pytest.ok"; exit $rc
'
phase bundle "test -s $BUNDLE" '
    t="$BUNDLE.tmp.$SLURM_JOB_ID"
    HF_HUB_OFFLINE=0 python -m qis.s02.tasks --out "$t" --spec "$BSPEC" --n-train 4000 --n-eval 64 > "$t.log"
    mv "$t" "$BUNDLE"; mv "$t.log" "$BUNDLE.log"
'
phase config "test -s $W/config.json" '
    sha=$(sha256sum "$BUNDLE" | cut -d" " -f1)
    python - <<PY
import json, os
cfg = json.loads(os.environ["CFG_JSON"])
cfg.update(run_id=os.environ["RUN"], attempt_id="a1", bundle=os.environ["BUNDLE"], bundle_sha256="$sha",
           model=os.environ["MODEL"], out_dir=os.environ["W"], ckpt_dir=os.environ["CK"],
           ckpt_lock_root=os.environ["S02"] + "/ckpt")
ic = cfg.get("init_ckpt")
if isinstance(ic, str) and ic.startswith("run:"):
    _, run, rnd = ic.split(":")
    cfg["init_ckpt"] = os.path.join(os.environ["S02"], "ckpt", run, "round_%04d" % int(rnd))
    assert os.path.isdir(cfg["init_ckpt"]), "init checkpoint missing: " + cfg["init_ckpt"]
json.dump(cfg, open(os.environ["W"] + "/config.json", "w"), indent=1)
PY
    cp "$W/config.json" "$AE_RESULTS/config.json"
'
phase train "test -f $W/RUN_COMPLETE" '
    rc=0; python -m qis.train.run --config "$W/config.json" >> "$W/stdout.log" 2>&1 || rc=$?
    grep -v "^INFO\|it/s\]" "$W/stdout.log" | tail -15
    cp "$W/metrics.jsonl" "$AE_RESULTS/metrics.jsonl" 2>/dev/null || true
    if [ $rc -eq 143 ]; then scontrol requeue $SLURM_JOB_ID; sleep 900; fi
    exit $rc
'
phase export "false" '
    cp "$W/metrics.jsonl" "$W/config.json" "$AE_RESULTS/"
    du -sh "$CK" > "$AE_RESULTS/ckpt_du.txt" 2>&1 || true
    # storage rule (2026-11-16 incident): after a complete run keep only the retained rounds
    keep=$(python -c "import json; print(\" \".join(\"round_%04d\" % r for r in json.load(open(\"$W/config.json\")).get(\"retain_rounds\", [])))")
    for r in "$CK"/round_*; do
        [ -d "$r" ] || continue
        case " $keep " in *" $(basename "$r") "*) echo "keep $r";; *) echo "prune $r"; rm -rf -- "$r";; esac
    done >> "$AE_RESULTS/ckpt_du.txt"
'
